        } else if (active.length) {
            console.log('  📍 stamp in-progress pr#' + pr.number +
                        ' (stampFn: ' + typeof stampFn + ')');
            try {
                stampFn(headSha, 'in_progress', null, active[0].html_url);
            } catch (e) {
                console.warn('  ⚠️  in-progress stamp threw: ' + (e.message || e));
