/**
 * Unit tests for js/smAgent.js
 *
 * Tests JQL interpolation, config loading, rule dispatch, and label skipping.
 *
 * Uses: configModule, configLoaderModule, loadModule(), makeRequire(), assert, test(), suite()
 */

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Create a smAgent instance with full mock injection.
 *
 * The key design: a fresh configLoader is created per test using the SAME
 * file_read mock, so config discovery paths are fully controlled by fileMap.
 *
 * file_read mock strategy:
 *   - Paths containing ".dmtools/config" → only accessible if listed in fileMap
 *     (ensures "no config" tests don't accidentally load the real project config)
 *   - All other paths → forwarded to the real file_read (for agent JSON configs etc.)
 *
 * @param {Object} opts
 *   fileMap        - { path: content } for config file discovery (config paths only)
 *   tickets        - tickets returned by jira_search_by_jql (default: [])
 *   fullTicket     - ticket returned by jira_get_ticket
 *   onTrigger      - fn(owner, repo, workflow, inputs, ref) called on triggerWorkflow
 *   onAddLabel     - fn(opts) called on jira_add_label
 *   onMoveStatus   - fn(opts) called on jira_move_to_status
 *   workflowRuns   - { queued: [], in_progress: [] } active workflow runs by status
 */
function smRealKeyModules() {
    var shapes = loadModule('js/common/ticketKeyShapes.js', makeRequire({}), {});
    var trackers = loadModule('js/common/trackers.js', makeRequire({ '../config.js': configModule, './ticketKeyShapes.js': shapes }), {});
    return {
        './validateInputJql.js': loadModule('js/common/validateInputJql.js', makeRequire({ './ticketKeyShapes.js': shapes, './trackers.js': trackers }), {}),
        './trackers.js': trackers
    };
}

function makeSmAgent(opts) {

/**
 * DMTools Agent Unit Test Runner
 *
 * Runs unit tests for agent JS scripts in GraalJS environment.
 * Provides: test(), suite(), assert, loadModule(), makeRequire(), trackersMock()
 *
 * Usage:
 *   dmtools run js/unit-tests/run_all.json
 *   dmtools run js/unit-tests/run_configLoader.json
 *   dmtools run js/unit-tests/run_smAgent.json
 */

// ── Global state ─────────────────────────────────────────────────────────────

var _results_ = { passed: 0, failed: 0, errors: [] };
var _currentSuite_ = 'default';

// Provide a stub java global for tests that mock java.lang.System.getenv.
// In a real GraalJS environment java is already present; we never overwrite it.
if (typeof java === 'undefined') {
    var _javaStub_ = { lang: { System: { getenv: function() { return null; } } } };
    if (typeof globalThis !== 'undefined') {
        globalThis.java = _javaStub_;
    } else if (typeof this !== 'undefined') {
        this.java = _javaStub_;
    }
}

// ── Network guard ────────────────────────────────────────────────────────────
// Unit tests must never reach a real service. Several tests fall through to the
// REAL host tool (github_*, confluence_* ...) when they do not mock it, which issued
