        console.log('CLI: ' + JSON.stringify(sm.capturedCliCommands.map(function (c) { return c.command; })));
        assert.ok(dispatched(sm.capturedCliCommands), 'armed PR on a bare moved head must get a re-dispatch');
    });
});
