    // runs the standard fail path.

    var RULES = {
        validateSkip: { source: 'github', query: { type: 'pr', labels: ['pr_approved'],
            notLabels: ['ai_validating'], notMergeState: ['BEHIND', 'DIRTY'], draft: false },
