        sm.action({ jobParams: { owner: 'a', repo: 'b', rules: [RULES.sweep] } });

        assert.ok(sm.capturedPrComments.length === 1 &&
            sm.capturedPrComments[0].body.indexOf('crash-loop') !== -1,
