        return cmdList.some(function (c) { return c.command.indexOf('gh workflow run') === 0; });
    }

    function runsCli(oldSha) {
        return function (cmd) {
            if (cmd.command.indexOf('actions/workflows/') !== -1 && cmd.command.indexOf('/runs?') !== -1) {
                var m = /head_sha=([^&"]+)/.exec(cmd.command);
                if (m && m[1] === oldSha) {
