                    if (m && m[1] === HEAD) {
                        return JSON.stringify({ workflow_runs: [
                            { status: 'completed', conclusion: 'cancelled', head_sha: HEAD,
                              created_at: cancelledAt, updated_at: cancelledAt },
                            { status: 'completed', conclusion: 'success', head_sha: HEAD,
